type LevelSummary = record(level: int, free: int)

fn level_summaries(spots: list<Spot>) -> list<LevelSummary>
    let groups: list<Spot> = group_by(spots, s => s.level)
    let mut result: list<LevelSummary> = []
    for g in groups
        let level = g.Key
        let free = g.Value |> count(s => not s.occupied)
        push(result, LevelSummary(level, free))
    return result |> sort_by(s => s.level)

